		Host: host, Port: 80, Method: firstLineMethod(request), Path: firstLinePath(request),
		Status: &status, Request: core.MsgPtr(reqID), Response: &respID, Source: core.SourceProxy,
	}
	s.store.AddExchange(ex)
	return ex.ID
}

