package main

import (
	"bufio"
	"crypto/sha1"
	"encoding/base64"
	"encoding/binary"
	"io"
	"log"
	"net/http"
	"os"
)

func readFrame(r *bufio.Reader) (byte, []byte, error) {
	h := make([]byte, 2)
	if _, err := io.ReadFull(r, h); err != nil {
		return 0, nil, err
	}
	op := h[0] & 0x0f
	masked := h[1]&0x80 != 0
	n := uint64(h[1] & 0x7f)
	switch n {
	case 126:
		b := make([]byte, 2)
		io.ReadFull(r, b)
		n = uint64(binary.BigEndian.Uint16(b))
	case 127:
		b := make([]byte, 8)
		io.ReadFull(r, b)
		n = binary.BigEndian.Uint64(b)
	}
	var key [4]byte
	if masked {
		io.ReadFull(r, key[:])
	}
	p := make([]byte, n)
	if _, err := io.ReadFull(r, p); err != nil {
		return 0, nil, err
	}
	if masked {
		for i := range p {
			p[i] ^= key[i%4]
		}
	}
	return op, p, nil
}

func frame(op byte, p []byte) []byte {
	out := []byte{0x80 | op}
	switch {
	case len(p) < 126:
		out = append(out, byte(len(p)))
	case len(p) < 65536:
		out = append(out, 126, byte(len(p)>>8), byte(len(p)))
	default:
		b := make([]byte, 8)
		binary.BigEndian.PutUint64(b, uint64(len(p)))
		out = append(append(out, 127), b...)
	}
	return append(out, p...)
}

func main() {
	addr := os.Args[1]
	log.Fatal(http.ListenAndServe(addr, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		key := r.Header.Get("Sec-WebSocket-Key")
		sum := sha1.Sum([]byte(key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"))
		conn, rw, err := w.(http.Hijacker).Hijack()
		if err != nil {
			return
		}
		defer conn.Close()
		rw.WriteString("HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: " +
			base64.StdEncoding.EncodeToString(sum[:]) + "\r\n\r\n")
		rw.Flush()
		for {
			op, p, err := readFrame(rw.Reader)
			if err != nil {
				return
			}
			if op == 8 {
				conn.Write(frame(8, []byte{0x03, 0xe8}))
				return
			}
			conn.Write(frame(op, append([]byte("echo: "), p...)))
			conn.Write(frame(8, []byte{0x03, 0xe8}))
			return
		}
	})))
}

