    await page.waitForSelector(`text=echo: hello e2e ${width}`, { timeout: 10000 });
    await page.screenshot({ path: `${OUT}ws-${width}.png`, fullPage: true });
    const overflowWS = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth + 1);
    if (overflowWS) problems.push(`[${width}] ws page scrolls horizontally`);

    // HTTP/2: add a CR/LF header in a blank row and preview.
    await page.goto(W + '/ui2/repeater/h2');
    const names = page.locator('input[name=name]');
    const n = await names.count();
    let blank = -1;
    for (let i = 0; i < n; i++) { if ((await names.nth(i).inputValue()) === '') { blank = i; break; } }
    if (blank < 0) fail('no blank header row');
    await names.nth(blank).fill('x-inject');
    await page.locator('input[name=value]').nth(blank).fill('a\\r\\nTransfer-Encoding: chunked');
    await page.click('button:has-text("Preview")');
    await page.waitForSelector('text=This request is kettled because');
    const rendering = await page.textContent('pre.msg');
    if (!rendering.includes('x-inject: a\\r\\nTransfer-Encoding: chunked')) fail('rendering missing escaped field: ' + rendering);
    await page.screenshot({ path: `${OUT}h2-${width}.png`, fullPage: true });

    // GraphQL: invalid then valid.
    await page.goto(W + '/ui2/repeater/graphql');
    await page.fill('#gql-query', '{ me { id }');
    await page.click('button:has-text("Validate query")');
    await page.waitForSelector('text=Invalid GraphQL document');
    await page.fill('#gql-query', '{ me { id } }');
    await page.click('button:has-text("Validate query")');
    await page.waitForSelector('text=Valid GraphQL document.');
    await page.screenshot({ path: `${OUT}graphql-${width}.png`, fullPage: true });
    await page.close();
  }
  await browser.close();
  if (problems.length) { console.error(problems.join('\n')); process.exitCode = 1; }
  console.log(process.exitCode ? 'E2E FAILED' : 'E2E OK');
})().catch((e) => { console.error(e); process.exit(1); });

